/**
 * Bundled official token logos for the common Starknet tokens, keyed by the
 * canonical (64-hex, zero-padded) contract address. Sourced once from the
 * CoinGecko Starknet token list (128px, so they stay crisp on high-DPI
 * displays) so the wallet shows correct, recognizable logos offline without
 * leaking token holdings to a logo CDN at render time.
 */
const TOKEN_LOGOS: Readonly<Record<string, string>> = {
  "0x0057912720381af14b0e5c87aa4718ed5e527eab60b3801ebf702ab09139e38b":
    "data:image/png;base64,",
  "0x049d36570d4e46f48e99674bd3fcc84644ddd6b96f7c741b1562b82f9e004dc7":
    "data:image/png;base64,",
  "0x00da114221cb83fa859dbdb4c44beeaa0bb37c7537ad5ae66fe5e0efd20e6eb3":
    "data:image/png;base64,",
  "0x03fe2b97c1fd336e750087d68b9b867997fd64a2661ff3ca5a7c771641e8e7ac":
    "data:image/png;base64,",
  "0x068f5c6a61780768455de69077e07e89787839bf8166decfbf92b645209c0fb8":
    "data:image/png;base64,",
  "0x053c91253bc9682c04929ca02ed00b3e423f6710d2ee7e0d5ebb06f3ecf368a8":
    "data:image/png;base64,",
  "0x04718f5a0fc34cc1af16a1cdee98ffb20c31f5cd61d6ab07201858f4287c938d":
    "data:image/png;base64,",
};

/**
 * Returns the bundled data-URI logo for a token address, or null when the
 * token is not one of the bundled common tokens (callers fall back to the
 * symbol badge or a watch-asset image).
 */
export const tokenLogo = (address: string): string | null => {
  let canonical: string;
  try {
    canonical = `0x${BigInt(address.trim().toLowerCase()).toString(16).padStart(64, "0")}`;
  } catch {
    return null;
  }
  return TOKEN_LOGOS[canonical] ?? null;
};
